Steps:
[GQL-OP guest_cart]
  query { cart(cartName: "default" storeId: "{{STORE_ID}}" currencyCode: "USD" cultureName: "en-US") { id loyaltyPoints { amount currency { code } } } }
[GQL-EXEC guest_cart]
